public RefreshFrequency xds()
{
    METInventSiteByLocationPolicyTmp     metInventSiteByLocationPolicyTmp;
    METUserSecurityGroupList             metUserSecurityGroupList, blankGroupList;
    METUserSecurityWarehouseList         metUserSecurityWarehouseList, blankWarehouseList;
    InventLocation                       inventLocation;
    Set                                  processedSiteKeys = new Set(Types::String);
    str                                  siteKey;

    Unchecked(Uncheck::XDS)
    {
        while select crosscompany InventSiteId, InventLocationId, DataAreaId from inventLocation
          group by InventSiteId, InventLocationId, DataAreaId
          join metUserSecurityWarehouseList
              where metUserSecurityWarehouseList.InventLocationId == inventLocation.InventLocationId
                  && metUserSecurityWarehouseList.Company == inventLocation.DataAreaId
          join metUserSecurityGroupList
              where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityWarehouseList.UserSecurityGroupId
                  && metUserSecurityGroupList.UserId == curUserId()
        {
            // Row per warehouse (exact match)
            metInventSiteByLocationPolicyTmp.InventSiteId    = inventLocation.InventSiteId;
            metInventSiteByLocationPolicyTmp.InventLocationId = inventLocation.InventLocationId;
            metInventSiteByLocationPolicyTmp.Company         = inventLocation.DataAreaId;
            metInventSiteByLocationPolicyTmp.insert();

            // One site-level row per unique site+company
            // covers InventDim records that have a SiteId but blank LocationId
            siteKey = inventLocation.InventSiteId + '#' + inventLocation.DataAreaId;
            if (inventLocation.InventSiteId && !processedSiteKeys.in(siteKey))
            {
                processedSiteKeys.add(siteKey);
                metInventSiteByLocationPolicyTmp.InventSiteId    = inventLocation.InventSiteId;
                metInventSiteByLocationPolicyTmp.InventLocationId = '';
                metInventSiteByLocationPolicyTmp.Company         = inventLocation.DataAreaId;
                metInventSiteByLocationPolicyTmp.insert();
            }
        }

        // Blank-group: covers InventDim records with no site and no location
        while select Company from blankWarehouseList
          group by Company
          join blankGroupList
          where blankGroupList.UserSecurityGroupId == blankWarehouseList.UserSecurityGroupId
              && blankGroupList.UserId == curUserId()
        {
            metInventSiteByLocationPolicyTmp.InventSiteId     = '';
            metInventSiteByLocationPolicyTmp.InventLocationId = '';
            metInventSiteByLocationPolicyTmp.Company          = blankWarehouseList.Company;
            metInventSiteByLocationPolicyTmp.insert();
        }
    }

    return RefreshFrequency::PerSession;
}
